class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        maxSub = nums[0]
        curSum = 0

        for n in nums:
            if curSum + n < n:
                curSum = 0
            curSum += n
            maxSub = max(curSum, maxSub)
        return maxSub

