def subsets(nums):
        subsets = []
        for num in nums:
            for subset_ind in range(len(subsets)):
                # iterate indexes because it may enter an infinite loop if iterated normally
                subsets.append(subsets[subset_ind] + [num])
            subsets.append([num])
        subsets.append([])

        return subsets

