class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        
        self.ans = False
        row, col = len(board), len(board[0])

        def dfs(i, j, index, visited = set()):
            if index == len(word):
                self.ans = True
                return
            b = {(i,j)}
            
            if i-1 > -1 and (i-1, j) not in visited and board[i-1][j] == word[index]:
                dfs(i-1, j, index+1, visited.union(b))
            if i+1 < row and (i+1, j) not in visited and board[i+1][j] == word[index]:
                dfs(i+1, j, index+1, visited.union(b))
            if j-1 > -1 and (i, j-1) not in visited and board[i][j-1] == word[index]:
                dfs(i, j-1, index+1, visited.union(b))
            if j+1 < col and (i, j+1) not in visited and board[i][j+1] == word[index]:
                dfs(i, j+1, index+1, visited.union(b))
            return
        
        for i in range(row):
            for j in range(col):
                if board[i][j] == word[0]:
                    dfs(i, j, 1)
                    if self.ans == True:
                        break
            if self.ans == True:
                break

        return self.ans

