When we are doing DFS - we do not keep track of visited nodes. If the graph has a cycle it can lead to infinite lopp

A bit improved version where we keep track of visited nodes

function dfs(graph, start) {

    const stack = [start]

    const visited = new Set()

    while (stack.length) {

        const curr = stack.pop()
        visited.add(curr)

        console.log(curr)

        for (let nei of graph[curr]) {

            if (!visited.has(nei)) {
                stack.push(nei)
            }
        }
    }
}

And this is for recursive version of DFS

function dfsRec(graph, start, visited = new Set()) {

    console.log(start)
    visited.add(start)

    for (let nei of graph[start]) {
        if (!visited.has(nei)) {
            dfsRec(graph, nei, visited)
        }
    }
}

