class Solution {
public:
    string longestPalindrome(string s) {
        if(s.length() == 1){
            return s;
        }
        string str = "";
        int len = 0;
        for(int i{0}; i<s.length(); i++){
            int start = i, end = i, curr_len = 0;
            string curr_string = "";

            if(i>0 && s[i] == s[i-1]){
                continue;
            }
            while(end<s.length() && s[start]==s[end]){
                curr_string += s[end];
                end++;
                curr_len++;
            }
            if(start > 0){
                start--;
            }

            while(start>=0 && end<s.length()){
                cout<<start<<" "<<end<<endl;
                if(s[start] != s[end]){
                    break;
                }
                
                curr_string = s[start] + curr_string + s[end];
                start--;
                end++;
                curr_len+=2;
            }

            if(curr_len > len){
                len = curr_len;
                str = curr_string;
                cout<<str<<endl;
            }
        }
        return str;
    }
};

