I have done the same problem using heapq module


import heapq

class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        hm={}
        for i in nums:
            if i not in hm.keys():
                hm[i]=1
            else:
                hm[i]=hm[i]+1
        list_hm=[(key,hm[key]) for key in hm.keys()]
        hp=[(freq,value) for value,freq in list_hm]
        heapq._heapify_max(hp)
        # print(hp)
        result=[]
        for i in range(k):
            x,y=heapq.heappop(hp)
            result.append(y)
            heapq._heapify_max(hp)
        return result

if __name__=="__main__":
    sol=Solution()
    l=[1,1,1,2,2,3]
    k = 2
    result=sol.topKFrequent(l,k)
    print(result)

