Bottom up DP
class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:        
        dp=[math.inf] * (amount+1)
        dp[0]=0

        for coin in coins:
            for i in range(coin, amount+1):
                if i-coin>=0:
                    dp[i]=min(dp[i], dp[i-coin]+1)

        return -1 if dp[-1]==math.inf else dp[-1]

Instead of resetting every time when you find 0 in the array. We can also use the element of array in comparison while deriving max and min at each level.

class Solution {
    public int maxProduct(int[] nums) {
        int n = nums.length, maxProd = nums[0], minProd = nums[0], res = nums[0];
        for(int i=1;i<n;i++){
            int max = maxProd;
            maxProd = Math.max(nums[i], Math.max(nums[i] * maxProd, nums[i] * minProd));
            minProd = Math.min(nums[i], Math.min(nums[i] * max, nums[i] * minProd));
            res = Math.max(res, maxProd);
        }
        return res;
    }
}

