My solution: find the pivot and do binary search on both arrays (left from pivot and right from pivot)

class Solution:
    @staticmethod
    def binary_search(nums: List[int], target: int) -> int:
        left, right = 0, len(nums) - 1
        first_true_index = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] >= target:
                if nums[mid] == target:
                    first_true_index = mid
                right = mid - 1
            else:
                left = mid + 1
        return first_true_index

    def search(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums) - 1
        first_true_index = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] <= nums[-1]:
                first_true_index = mid
                right = mid -1
            else:
                left = mid + 1
        result_1 = self.binary_search(nums[:first_true_index], target)
        result_2 = self.binary_search(nums[first_true_index:], target)
        if result_1 != -1:
            return result_1
        if result_2 != -1:
            return len(nums[:first_true_index]) + result_2
        return -1

