class Solution:
    def __init__(self):
        self.is_balanced = True

    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        def dfs(root):
            if not root:
                return 0
            left = dfs(root.left)
            right = dfs(root.right)
            if abs(left - right) > 1:
                self.is_balanced = False
            return 1 + max(left, right)
        dfs(root)
        return self.is_balanced if root else True

